package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.util.*;
import java.util.concurrent.*;
@androidx.media3.common.util.UnstableApi
public class OndaFilesActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private final ArrayList<OndaFiles.Item> items=new ArrayList<>(),shown=new ArrayList<>();private final ArrayDeque<Uri> parents=new ArrayDeque<>();private final ArrayDeque<String> names=new ArrayDeque<>();private Uri directory;private String path="Onda";private int generation,sort;private boolean loading;private TextView status;private EditText search;private Rows adapter;
 @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,12)+i.getSystemWindowInsetBottom());return i;});setContentView(root);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹",v->onBackPressed()),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));bar.addView(Ui.text(this,"Arquivos do Onda",21,Ui.TEXT),new LinearLayout.LayoutParams(0,-2,1));bar.addView(Ui.menuButton(this,"Menu dos arquivos",v->Ui.menu(this,v,new String[]{"Ordenar arquivos","Recarregar pasta","Configurar pasta","Conversor local"},new String[]{"Ordenar arquivos","Recarregar pasta","Configurar pasta","Conversor local"},new Runnable[]{this::sort,()->load(directory),()->startActivity(new Intent(this,DownloadCenterActivity.class)),()->startActivity(new Intent(this,LocalConverterActivity.class))})),new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));root.addView(bar);search=new EditText(this);Ui.input(search);search.setHint("Buscar nesta pasta");search.setContentDescription("Buscar nos arquivos do Onda");root.addView(search);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int count,int after){}public void onTextChanged(CharSequence s,int a,int before,int count){render();}public void afterTextChanged(Editable e){}});status=Ui.text(this,"Abrindo pasta…",13,Ui.MUTED);root.addView(status);ListView list=new ListView(this);list.setDivider(null);adapter=new Rows();list.setAdapter(adapter);list.setOnItemClickListener((p,v,n,id)->open(shown.get(n)));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));root.addView(Ui.text(this,"Lista até 1.000 itens por pasta. A busca vale para a pasta aberta. Pastas de nuvem dependem do provedor e da conexão.",12,Ui.MUTED));load(null);}
 private void load(Uri target){int request=++generation;loading=true;status.setText("Lendo pasta…");worker.execute(()->{try{Uri folder=target;if(folder==null){String tree=getSharedPreferences(OndaFolders.PREF,0).getString("tree","");if(tree.isEmpty())throw new java.io.IOException("Configure a pasta do Onda pelo menu → Configurar pasta.");folder=OndaFolders.root(this,Uri.parse(tree));}List<OndaFiles.Item> result=OndaFiles.list(this,folder);Uri current=folder;runOnUiThread(()->{if(isDestroyed()||request!=generation)return;loading=false;directory=current;items.clear();items.addAll(result);render();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()&&request==generation){loading=false;items.clear();shown.clear();adapter.notifyDataSetChanged();status.setText(e.getMessage());}});}});}
 private void render(){if(adapter==null)return;shown.clear();String query=search.getText().toString();for(OndaFiles.Item item:items)if(SearchText.matches(item.name,query))shown.add(item);shown.sort(OndaFiles.order(sort));adapter.notifyDataSetChanged();status.setText(path+" • "+shown.size()+" de "+items.size()+" itens"+(items.size()==1000?" • limite da pasta":""));}
 private void sort(){new AlertDialog.Builder(this).setTitle("Ordenar arquivos").setSingleChoiceItems(new String[]{"Nome A–Z","Mais recentes","Maior tamanho"},sort,(d,n)->{sort=n;render();d.dismiss();}).setNegativeButton("Fechar",null).show();}
 private void open(OndaFiles.Item item){if(loading)return;if(item.folder){if(parents.size()>=30){Toast.makeText(this,"Limite de 30 níveis de pastas",Toast.LENGTH_SHORT).show();return;}parents.push(directory);names.push(path);path+="/"+item.name;search.setText("");load(item.uri);return;}String mime=OndaFiles.supportedMime(item);if(mime.isEmpty()){Toast.makeText(this,"Este tipo de arquivo não é aberto pelo Onda",Toast.LENGTH_SHORT).show();return;}Class<?> activity=mime.startsWith("video/")?VideoActivity.class:mime.equals("application/pdf")?PdfActivity.class:MainActivity.class;String type=mime;new AlertDialog.Builder(this).setTitle(item.name).setItems(type.equals("application/pdf")?new String[]{"Abrir no Onda"}:new String[]{"Abrir no Onda","Converter áudio"},(d,n)->{try{if(n==1)startActivity(new Intent(this,LocalConverterActivity.class).putExtra("local_source",item.uri.toString()));else startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(item.uri,type).setClass(this,activity).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){status.setText("Não foi possível abrir. Confira o acesso à pasta e o formato.");}}).setNegativeButton("Fechar",null).show();}
 private final class Rows extends BaseAdapter{public int getCount(){return shown.size();}public Object getItem(int n){return shown.get(n);}public long getItemId(int n){return n;}public View getView(int n,View old,ViewGroup parent){LinearLayout box;if(old instanceof LinearLayout)box=(LinearLayout)old;else{box=new LinearLayout(OndaFilesActivity.this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(Ui.dp(OndaFilesActivity.this,12),Ui.dp(OndaFilesActivity.this,12),Ui.dp(OndaFilesActivity.this,12),Ui.dp(OndaFilesActivity.this,12));box.addView(Ui.text(OndaFilesActivity.this,"",16,Ui.TEXT));box.addView(Ui.text(OndaFilesActivity.this,"",12,Ui.MUTED));Ui.card(box,false);}OndaFiles.Item item=shown.get(n);((TextView)box.getChildAt(0)).setText((item.folder?"▸ ":"")+item.name);((TextView)box.getChildAt(1)).setText(item.folder?"Pasta":(item.size<0?"Tamanho não informado":android.text.format.Formatter.formatShortFileSize(OndaFilesActivity.this,item.size)));return box;}}
 @Override public void onBackPressed(){if(!parents.isEmpty()){Uri parent=parents.pop();path=names.pop();search.setText("");load(parent);}else super.onBackPressed();}@Override public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
